head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDFIS00300_P1.xml";
scwin.fn_GetPar;
scwin.fn_SetPar;
scwin.v_arrKey = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //조회조건이 담길 배열

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_AudtOpin.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 감사의견 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(pan_Ctnt);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + scwin.v_arrKey[2] + "&outputMessageId=FIS_AUDT_OPIN" + "&param01=" + scwin.v_arrKey[0] + "&param02=" + scwin.v_arrKey[1];
    dts_AudtOpin.DataID = encodeURI(url);
    dts_AudtOpin.Reset();
};


/**
 * 컨텐츠 append
 */
scwin.fn_AppendContents = function() {
    var strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:250px;font-family:돋움체;'>";
    for (var nRow = 1; nRow <= dts_AudtOpin.getTotalRow(); nRow++) {
        strContent = strContent + dts_AudtOpin.getCellData(nRow, "AUDT_OPIN") + "<br/>";
    }
    strContent = strContent + "</div>";
    pan_Ctnt.innerHTML = strContent;
    $c.cm.CloseWin(dts_AudtOpin.getTotalRow(), pan_Ctnt);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top); // 패널라운드 처리
    window.document.body.scroll = "no";
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    var parentWin = $c.frame.path("../");
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        scwin.v_arrKey = arrPar;
    }
    if (scwin.v_arrKey.length >= 1) {
        scwin.fn_Search();
    } else {
        $c.win.alert("조회 조건이 없습니다");
    }
};
scwin.dts_AudtOpin_OnLoadError = function() {
    $c.cm.CloseWin(-1, pan_Ctnt);
    $c.stf.alert_error(dts_AudtOpin);
};
scwin.dts_AudtOpin_OnLoadCompleted = function(rowcount) {
    if (dts_AudtOpin.errorMsg) {
        $c.win.alert(dts_AudtOpin.errorMsg);
    }

    // 멀티Row의 데이터를 하나로 합치자.
    scwin.fn_AppendContents();
};
scwin.img_Close_onclick = async function() {
    // 닫기 버튼 클릭
    await $c.frame.CloseFrame();
};
